if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js?v=2810').then(r=>r.update()).catch(()=>{});}

const SUPABASE='https://yweluzclearwrazdkahu.supabase.co',API=SUPABASE+'/functions/v1/vacleaner-admin-bookings-v2',KEY='sb_publishable_-UdAKDf5jzIP6N9rBp927g_VhyJKeog';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=v=>new Intl.NumberFormat('uk-UA').format(Number(v)||0)+' грн';
const date=v=>{const a=String(v||'').slice(0,10).split('-');return a.length===3?`${a[2]}.${a[1]}`:'—'};
const DEFAULT_SLOTS={morningStart:'07:00',morningEnd:'09:30',eveningStart:'17:30',eveningEnd:'20:00'};
function getSlots(){try{return {...DEFAULT_SLOTS,...JSON.parse(localStorage.getItem('vacleaner_slots')||'{}')}}catch{return {...DEFAULT_SLOTS}}}
function saveSlots(v){localStorage.setItem('vacleaner_slots',JSON.stringify(v))}
function slotForTime(t){const s=getSlots();return t>=s.eveningStart?'evening':'morning'}
function timesBetween(start,end,step=30){const out=[];let [h,m]=start.split(':').map(Number),[eh,em]=end.split(':').map(Number),cur=h*60+m,last=eh*60+em;for(;cur<=last;cur+=step)out.push(String(Math.floor(cur/60)).padStart(2,'0')+':'+String(cur%60).padStart(2,'0'));return out}
function windowButtons(name,value){const s=getSlots();return `<div class="window-choice"><label><input type="radio" name="${name}" value="morning" ${value==='morning'?'checked':''}><span><b>Ранок</b><small>${s.morningStart}–${s.morningEnd}</small></span></label><label><input type="radio" name="${name}" value="evening" ${value==='evening'?'checked':''}><span><b>Вечір</b><small>${s.eveningStart}–${s.eveningEnd}</small></span></label></div>`}
function timeChipPicker(name,value){return `<div class="time-chip-picker" data-time-picker="${name}"><input type="hidden" name="${name}" value="${value}"><div class="time-chip-list"></div></div>`}
function bindTimeWindows(form){['pickup','return'].forEach(kind=>{const windowName=kind+'Window',timeName=kind+'Time',picker=form.querySelector(`[data-time-picker="${timeName}"]`),hidden=picker?.querySelector('input');if(!picker||!hidden)return;const draw=()=>{const code=form.querySelector(`input[name="${windowName}"]:checked`)?.value||'morning',s=getSlots(),start=code==='morning'?s.morningStart:s.eveningStart,end=code==='morning'?s.morningEnd:s.eveningEnd,vals=timesBetween(start,end),selected=vals.includes(hidden.value)?hidden.value:start;hidden.value=selected;picker.querySelector('.time-chip-list').innerHTML=vals.map(v=>`<button type="button" class="time-chip ${v===selected?'active':''}" data-time="${v}">${v}</button>`).join('');picker.querySelectorAll('.time-chip').forEach(btn=>btn.onclick=()=>{hidden.value=btn.dataset.time;picker.querySelectorAll('.time-chip').forEach(x=>x.classList.toggle('active',x===btn))})};form.querySelectorAll(`input[name="${windowName}"]`).forEach(r=>r.onchange=draw);draw()})}

const statusText={pending:'Нова',waiting_payment:'Очікує передплату',confirmed:'Підтверджена',issued:'Видана',completed:'Повернена',cancelled:'Скасована',declined:'Відхилена'};
const products={puzzi:'Kärcher Puzzi',puzzi_jimmy:'Puzzi + Jimmy',sc2:'Kärcher SC 2',abir:'Робот ABIR',combo:'Комбо · Puzzi + SC 2',general:'Генеральне',ideal_windows:'Ідеальні вікна',elite:'HOME RESET'};
const EXTRA_CATALOG={premium_sc2:{label:'Насадки «Преміум» до SC 2',price:200,requires:['sc2','combo','general','ideal_windows','elite']},odour_zero:{label:'Odour Zero',price:250},neutralix:{label:'Neutralix · концентрат',price:250},shower_care:{label:'Shower Care',price:250},soft_degreaser:{label:'Soft Degreaser',price:250},grill_force:{label:'Grill Force',price:250},scalex_pro:{label:'Scalex Pro',price:250},eco_clean:{label:'Eco Clean',price:250},glass_perfect:{label:'Glass Perfect Care',price:150}};
function getSelectedExtras(b){const rows=b?.extras?.selected_items;return Array.isArray(rows)?rows:[]}
function extrasTotal(b){return getSelectedExtras(b).reduce((n,x)=>n+Number(x.price||0),0)}
function extrasInline(b){const x=getSelectedExtras(b);return x.length?`${x.map(i=>i.label).join(' + ')} · ${money(extrasTotal(b))}`:''}
function normalizePhone(value){const d=String(value||'').replace(/\D/g,'');if(d.length===10&&d.startsWith('0'))return '+38'+d;if(d.length===12&&d.startsWith('380'))return '+'+d;return ''}
function loyaltyLabel(profile){if(!profile)return'';const l=profile.loyalty||{level:'Start',percent:0};return `${l.level}${l.percent?` · −${l.percent}% на техніку`:''}`}
function loyaltyFromBooking(b){const l=b?.extras?.loyalty;return l&&typeof l==='object'?l:null}

const imgs={puzzi:'/assets/puzzi.webp',sc2:'/assets/sc2.webp',jimmy:'/assets/jimmy.webp',abir:'/assets/abir.webp'};
const state={session:null,bookings:[],calendar:[],view:'bookings',filter:'all',detail:null,listScroll:0};
function getSession(){try{return JSON.parse(localStorage.getItem('vacleaner_session')||'null')}catch{return null}}
function saveSession(s){state.session=s;localStorage.setItem('vacleaner_session',JSON.stringify(s))}
function clearSession(){state.session=null;localStorage.removeItem('vacleaner_session')}
async function login(email,password){const r=await fetch(SUPABASE+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const d=await r.json();if(!r.ok)throw new Error('Невірний логін або пароль');saveSession(d);return d}
async function refresh(){const s=getSession();if(!s?.refresh_token)throw new Error('Сесія завершена');const r=await fetch(SUPABASE+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json();if(!r.ok)throw new Error('Сесія завершена');saveSession(d);return d}
async function invoke(body,retry=true){let s=getSession();if(!s?.access_token)throw new Error('Сесія завершена');let r=await fetch(API,{method:'POST',headers:{Authorization:`Bearer ${s.access_token}`,apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});if(r.status===401&&retry){await refresh();return invoke(body,false)}const d=await r.json().catch(()=>({error:'service_error'}));if(!r.ok)throw new Error(d.error||'Помилка сервера');return d}
function toast(t){const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),2300)}
function tval(b,k){const s=getSlots();return b?.extras?.[k]||('pickup_time'===k?(b.pickup_window==='morning'?s.morningStart:s.eveningStart):(b.return_window==='morning'?s.morningEnd:s.eveningEnd))}
function isPuzzi(b){return ['puzzi','puzzi_jimmy','combo','general','elite'].includes(b.product_code)}
function chem(b){const c=b.extras?.chemistry||b.extras?.finance||{};return{used:Number(c.used_packets||0),story:c.story_mention===true}}
function calc(b,override={}){const c=chem(b),used=override.used??c.used,story=override.story??c.story,expectedIssue=Number(b.deposit_amount||0),issuePaid=override.issuePaid??(b.deposit_paid===true),issue=override.issue??(issuePaid?expectedIssue:0),pre=b.prepayment_paid===false?0:Number(b.prepayment_amount||200),chemistry=isPuzzi(b)?Math.max(used-(story?2:0),0)*50:0,discount=Number(b.extras?.discount?.percent||0),extraItems=extrasTotal(b),cancelled=['cancelled','declined'].includes(b.status),expenses=cancelled?0:Number(b.base_amount||0)+Number(b.delivery_amount||0)+extraItems+chemistry,paid=pre+Number(issue||0),balance=paid-expenses;return{used,story,expectedIssue,issuePaid,issue,pre,chemistry,extraItems,discount,cancelled,expenses,paid,refund:cancelled?paid:Math.max(balance,0),due:cancelled?0:Math.max(-balance,0)}}
function pimgs(b){const c=b.product_code;if(c==='puzzi')return[imgs.puzzi];if(c==='sc2')return[imgs.sc2];if(c==='abir')return[imgs.abir];if(c==='puzzi_jimmy')return[imgs.puzzi,imgs.jimmy];if(c==='combo')return[imgs.puzzi,imgs.sc2];if(c==='general')return[imgs.puzzi,imgs.sc2,imgs.jimmy];if(c==='ideal_windows')return[imgs.sc2,imgs.abir];if(c==='elite')return[imgs.puzzi,imgs.sc2,imgs.jimmy,imgs.abir];return[]}
async function load(){const [b,c]=await Promise.all([invoke({action:'list',status:''}),invoke({action:'calendar',from:new Date().toISOString().slice(0,10),days:14})]);state.bookings=b.bookings||[];state.calendar=c.days||[];renderBadges()}
const ico={book:'<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>',cal:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="17" rx="2"/><path d="M8 2v4M16 2v4M3 9h18"/></svg>',msg:'<svg viewBox="0 0 24 24"><path d="M21 15a4 4 0 0 1-4 4H8l-5 3V7a4 4 0 0 1 4-4h10a4 4 0 0 1 4 4z"/></svg>',tech:'<svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="M7 9h10M8 19v2M16 19v2"/></svg>',clients:'<svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2"/><path d="M3 20c0-4 2-6 6-6s6 2 6 6M15 15c3 0 5 2 5 5"/></svg>',chart:'<svg viewBox="0 0 24 24"><path d="M4 20V10M10 20V4M16 20v-7M22 20V7"/></svg>',chem:'<svg viewBox="0 0 24 24"><path d="M9 3h6M10 3v5l-5 9a3 3 0 0 0 3 4h8a3 3 0 0 0 3-4l-5-9V3"/><path d="M7 16h10"/></svg>',gear:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1z"/></svg>'};
function shell(){document.body.innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="brand-mark">VA</div><div class="brand-copy"><strong>VAcleaner</strong><span>Календар оренди</span></div></div><nav class="nav">${nav('bookings','Бронювання',ico.book)}${nav('calendar','Календар',ico.cal)}${nav('upcoming','Найближчі',ico.msg)}${nav('equipment','Техніка',ico.tech)}${nav('clients','Клієнти',ico.clients)}${nav('analytics','Аналітика',ico.chart)}${nav('chemistry','Хімія',ico.chem)}${nav('settings','Налаштування',ico.gear)}</nav><div class="sidebar-footer"><div class="profile"><div class="avatar">V</div><div><strong>Vadim</strong><small>Адміністратор</small></div></div><button class="logout">Вийти</button></div></aside><header class="topbar"><label class="search">⌕<input id="globalSearch" placeholder="Пошук по бронюваннях, клієнтах…"></label><div class="top-spacer"></div><button class="icon-btn">${ico.msg}<span class="badge hidden" id="topBadge"></span></button><button class="new-btn" id="newBooking">＋ Нове бронювання</button></header><main class="main"><div class="page-head"><div><h1 id="pageTitle">Бронювання</h1><p id="pageSub">Усі заявки та керування орендою</p></div></div><section id="view"></section></main></div><div id="layer"></div>`;bindShell()}
function nav(id,label,icon){return`<button data-view="${id}" class="${id==='bookings'?'active':''}">${icon}<span>${label}</span>${id==='bookings'?'<b class="badge hidden" id="navBadge"></b>':''}</button>`}
function bindShell(){$$('.nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('.logout').onclick=()=>{clearSession();location.reload()};$('#newBooking').onclick=()=>openBookingForm();$('#globalSearch').oninput=()=>render();}
function renderBadges(){const n=state.bookings.filter(b=>b.status==='pending').length;['topBadge','navBadge'].forEach(id=>{const e=$('#'+id);if(e){e.textContent=n;e.classList.toggle('hidden',!n)}})}
function setHead(t,s){$('#pageTitle').textContent=t;$('#pageSub').textContent=s}
function switchView(v){state.view=v;$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
function render(){const v=state.view;if(v==='bookings'){setHead('Бронювання','Усі заявки та керування орендою');renderBookings()}if(v==='calendar'){setHead('Календар','Доступність техніки по днях і часових слотах');renderCalendar()}if(v==='upcoming'){setHead('Найближчі','Видачі, доставки та повернення, які потребують уваги');renderUpcoming()}if(v==='equipment'){setHead('Техніка','Уся техніка, комплекти й актуальні ціни');renderEquipment()}if(v==='clients'){setHead('Клієнти','Історія оренд, контакти та повторні замовлення');renderClients()}if(v==='analytics'){setHead('Аналітика','Виручка, завантаження та популярність техніки');renderAnalytics()}if(v==='chemistry'){setHead('Хімія','Контроль використання пакетиків і бонусів за сторіс');renderChemistry()}if(v==='settings'){setHead('Налаштування','Правила оренди, часові слоти й фінансова логіка');renderSettings()}}
function filtered(){let x=state.bookings;if(state.filter!=='all')x=x.filter(b=>b.status===state.filter);const s=$('#globalSearch')?.value.trim().toLowerCase();if(s)x=x.filter(b=>`${b.booking_code} ${b.customer_name} ${b.customer_phone} ${b.product_label}`.toLowerCase().includes(s));return [...x].sort((a,b)=>{const p={pending:0,waiting_payment:1,confirmed:2,issued:3,completed:4,cancelled:5};return(p[a.status]??9)-(p[b.status]??9)||new Date(a.start_at)-new Date(b.start_at)})}
function renderBookings(){const counts={all:state.bookings.length};['pending','waiting_payment','confirmed','issued','completed','cancelled'].forEach(s=>counts[s]=state.bookings.filter(b=>b.status===s).length);$('#view').innerHTML=`<div class="toolbar booking-toolbar"><button class="compact-toggle" id="compactToggle">${localStorage.getItem('vac_compact')==='1'?'Звичайний вигляд':'Компактний вигляд'}</button>${[['all','Усі'],['pending','Нові'],['waiting_payment','Очікують'],['confirmed','Підтверджені'],['issued','Видані'],['completed','Повернені'],['cancelled','Скасовані']].map(([k,l])=>`<button class="chip ${state.filter===k?'active':''}" data-filter="${k}"><span>${l}</span><b>${counts[k]||0}</b></button>`).join('')}</div><div class="booking-list">${filtered().map(bookingCard).join('')||'<div class="card empty">Нічого не знайдено.</div>'}</div>`;$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderBookings()});const ct=$('#compactToggle');if(ct)ct.onclick=()=>{localStorage.setItem('vac_compact',localStorage.getItem('vac_compact')==='1'?'0':'1');renderBookings()};document.querySelector('.booking-list')?.classList.toggle('compact',localStorage.getItem('vac_compact')==='1');bindCards()}
function bookingCard(b){const f=calc(b),mainAction=b.status==='confirmed'?'Видати техніку':b.status==='issued'?'Закрити оренду':b.status==='pending'||b.status==='waiting_payment'?'Підтвердити':'';return`<article class="card booking-card booking-row" data-id="${b.id}"><div class="booking-row-head"><div class="booking-identity"><small>${b.booking_code}</small><h2>${b.product_label}</h2><span>${(b.source||'сайт').replaceAll('_',' ')}</span></div><span class="status ${b.status}">${statusText[b.status]}</span></div><div class="booking-row-body"><div class="booking-time"><small>Період оренди</small><strong>${date(b.start_date)} · ${tval(b,'pickup_time')} <i>→</i> ${date(b.return_date)} · ${tval(b,'return_time')}</strong><span>${b.rental_days||1} доб.</span></div><div class="booking-person"><small>Клієнт</small><strong>${b.customer_name}</strong><a href="tel:${b.customer_phone}">${b.customer_phone}</a></div><div class="booking-delivery"><small>Видача</small><strong>${b.fulfillment==='delivery'?'Доставка':'Самовивіз'}</strong><span>${b.fulfillment==='delivery'?money(b.delivery_amount):'0 грн'} · ${b.fulfillment_address||'Європейська, 146Е'}</span></div><div class="booking-finance"><small>Фінанси</small><strong>${money(b.total_amount)}</strong><span>${f.issue?`залог ${money(f.issue)}`:'залог не внесено'}${f.discount?` · знижка ${f.discount}%`:''}${loyaltyFromBooking(b)?.level&&loyaltyFromBooking(b).level!=='Start'?` · ${loyaltyFromBooking(b).level}`:''}</span><em class="${f.refund?'refund':f.due?'due':'neutral'}">${f.refund?'повернути ':f.due?'доплата ':'баланс '}${money(f.refund||f.due)}</em></div></div>${extrasInline(b)?`<div class="booking-extra"><span>Додатково</span><strong>${extrasInline(b)}</strong></div>`:''}${b.customer_comment?`<div class="booking-note"><span>Коментар</span>${b.customer_comment}</div>`:''}<div class="actions booking-actions">${actions(b)}</div></article>`}
function actions(b){let m='';if(['pending','waiting_payment'].includes(b.status))m='<button class="btn primary" data-action="confirm">Підтвердити</button>';if(b.status==='confirmed')m='<button class="btn green" data-action="issue">Видати техніку</button>';if(b.status==='issued')m='<button class="btn green" data-action="complete">Закрити оренду</button>';return`${b.customer_telegram?'<button class="btn" data-action="telegram">Telegram</button>':''}<button class="btn" data-action="edit">Редагувати</button><button class="btn" data-action="finance">Розрахунок</button>${m}${!['completed','cancelled'].includes(b.status)?'<button class="btn danger secondary-danger" data-action="cancel">Скасувати</button>':''}`}
function bindCards(){$$('.booking-card').forEach(c=>{const b=state.bookings.find(x=>x.id===c.dataset.id);c.onclick=e=>{if(e.target.closest('button,a,input'))return;openDetail(b)};$$('[data-action]',c).forEach(btn=>btn.onclick=e=>{e.stopPropagation();handleAction(b,btn.dataset.action)})})}
async function handleAction(b,a){try{if(a==='confirm')return updateStatus(b,'confirmed');if(a==='issue')return openIssue(b);if(a==='complete')return openFinance(b,true);if(a==='finance')return openFinance(b,false);if(a==='edit')return openBookingForm(b);if(a==='telegram')return copyTelegram(b);if(a==='cancel'&&confirm('Скасувати бронювання?'))return updateStatus(b,'cancelled')}catch(e){toast(e.message)}}
async function updateStatus(b,status){await invoke({action:'update',bookingId:b.id,status,adminNote:b.admin_note||''});await load();render();if(state.detail?.id===b.id)openDetail(state.bookings.find(x=>x.id===b.id));toast('Статус оновлено')}
function copyTelegram(b){const f=calc(b),txt=[`Дата📆: ${date(b.start_date)} ${tval(b,'pickup_time')}`,`Оренда🚀: ${b.product_label}`,`Ціна💶: ${money(b.total_amount)}`,`Бронювання: ${money(b.prepayment_amount||200)}`,`Залоговий платіж: +${money(f.issue)}`,`Адреса📫: ${b.fulfillment_address||'Полтава, вул. Європейська, 146Е'}`,`Тел: ${b.customer_phone}`,`${b.customer_name}${b.customer_telegram?' · '+b.customer_telegram:''}`].join('\n');navigator.clipboard.writeText(txt).then(()=>toast('Текст скопійовано'))}
function availabilityClass(v,capacity){if(v===0)return 'zero';if(v<capacity)return 'low';return 'full'}
function renderCalendar(){$('#view').innerHTML=`<div class="calendar-summary"><div><strong>${state.calendar.length}</strong><span>днів у календарі</span></div><p>Повна доступність приглушена. Бурштин — залишилась 1 одиниця, червоний — зайнято. Натисніть слот, щоб створити бронювання.</p></div><div class="calendar-grid">${state.calendar.map(d=>`<article class="card day-card"><header><strong>${new Intl.DateTimeFormat('uk-UA',{weekday:'short',day:'2-digit',month:'2-digit'}).format(new Date(d.date+'T12:00:00'))}</strong><span>${d.date}</span></header><div class="day-labels"><span>Техніка</span><span>Ранок</span><span>Вечір</span></div>${Object.entries(d.resources).map(([k,r])=>`<div class="day-row"><b>${({puzzi:'Puzzi',sc2:'SC 2',jimmy:'Jimmy',abir:'ABIR'})[k]||r.label}</b><button class="slot ${availabilityClass(r.morning,r.capacity)}" data-calendar-slot data-date="${d.date}" data-product="${k}" data-window="morning" ${r.morning===0?'disabled':''}>${r.morning===r.capacity?'Вільно':r.morning===0?'Зайнято':`Залишилось ${r.morning}`}</button><button class="slot ${availabilityClass(r.evening,r.capacity)}" data-calendar-slot data-date="${d.date}" data-product="${k}" data-window="evening" ${r.evening===0?'disabled':''}>${r.evening===r.capacity?'Вільно':r.evening===0?'Зайнято':`Залишилось ${r.evening}`}</button></div>`).join('')}</article>`).join('')}</div>`;$$('[data-calendar-slot]').forEach(btn=>btn.onclick=()=>openBookingForm(null,{startDate:btn.dataset.date,productCode:btn.dataset.product,pickupWindow:btn.dataset.window}))}
function renderUpcoming(){
  const events=[];
  state.bookings.filter(b=>['waiting_payment','confirmed','issued'].includes(b.status)).forEach(b=>{
    if(b.status!=='issued')events.push({kind:'issue',date:b.start_date,time:tval(b,'pickup_time'),b});
    events.push({kind:'return',date:b.return_date,time:tval(b,'return_time'),b});
  });
  events.sort((a,b)=>`${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`));
  const groups=new Map();events.forEach(e=>{if(!groups.has(e.date))groups.set(e.date,[]);groups.get(e.date).push(e)});
  $('#view').innerHTML=events.length?`<div class="upcoming-board">${[...groups.entries()].map(([day,items])=>`<section class="upcoming-day"><header><div><span>${date(day)}</span><small>${new Intl.DateTimeFormat('uk-UA',{weekday:'long'}).format(new Date(day+'T12:00:00'))}</small></div><b>${items.length} ${items.length===1?'подія':'події'}</b></header><div class="upcoming-list">${items.map(upcomingRow).join('')}</div></section>`).join('')}</div>`:'<div class="card empty">Немає найближчих видач або повернень.</div>';
  bindUpcoming();
}
function upcomingRow(e){const b=e.b,isIssue=e.kind==='issue',delivery=b.fulfillment==='delivery',action=isIssue?(b.status==='waiting_payment'?'confirm':'issue'):'complete',actionLabel=isIssue?(b.status==='waiting_payment'?'Підтвердити оплату':'Видати техніку'):'Прийняти повернення';return`<article class="upcoming-row ${e.kind}" data-id="${b.id}"><div class="upcoming-time"><i>${isIssue?'↑':'↓'}</i><strong>${e.time}</strong><span>${isIssue?'Видача':'Повернення'}</span></div><div class="upcoming-main"><div class="upcoming-title"><h3>${b.product_label}</h3><span class="status ${b.status}">${statusText[b.status]}</span></div><p>${b.customer_name} · <a href="tel:${b.customer_phone}">${b.customer_phone}</a></p><small>${isIssue?(delivery?`Доставка · ${b.fulfillment_address||'адресу не вказано'}`:'Самовивіз · вул. Європейська, 146Е'):'Очікується повернення техніки'}</small></div><div class="upcoming-money"><small>${isIssue?'Бронювання':'Залог'}</small><strong>${money(isIssue?(b.prepayment_paid?b.prepayment_amount||200:0):calc(b).issue)}</strong></div><div class="upcoming-actions"><button class="btn subtle" data-up="open">Відкрити</button>${b.customer_telegram?'<button class="btn subtle" data-up="telegram">Telegram</button>':''}<button class="btn ${isIssue?'primary':'green'}" data-up="${action}">${actionLabel}</button></div></article>`}
function bindUpcoming(){$$('.upcoming-row').forEach(row=>{const b=state.bookings.find(x=>x.id===row.dataset.id);row.onclick=e=>{if(e.target.closest('button,a'))return;openDetail(b)};$$('[data-up]',row).forEach(btn=>btn.onclick=e=>{e.stopPropagation();const a=btn.dataset.up;if(a==='open')openDetail(b);else if(a==='telegram')copyTelegram(b);else handleAction(b,a)})})}
function renderEquipment(){const u=[['puzzi','Миючий пилосос','Kärcher Puzzi 8/1','Дивани, матраци, крісла, килими та текстиль.',700,800],['sc2','Пароочисник','Kärcher SC 2 Deluxe','Кухня, плитка, ванна, шви та тверді поверхні.',500,600],['jimmy','Пиловий пилосос','Jimmy JV35','Матраци й м’які поверхні. Надається разом із Puzzi.',350,350],['abir','Робот для вікон','ABIR WD8','Вікна, плитка, дзеркала та скляні поверхні.',800,900]],kits=[['Комбо','Puzzi + SC 2',['puzzi','sc2'],1000,1200,1800],['Генеральне прибирання','Puzzi + SC 2 + Jimmy',['puzzi','sc2','jimmy'],1300,1400,2200],['Ідеальні вікна','SC 2 + ABIR',['sc2','abir'],1200,1300,1900],['HOME RESET','Puzzi + SC 2 + Jimmy + ABIR',['puzzi','sc2','jimmy','abir'],2300,2500,3500]];$('#view').innerHTML=`<div class="equipment-grid">${u.map(x=>`<article class="card equipment-card"><div class="equipment-image single"><img src="${imgs[x[0]]}" alt="${x[2]}"></div><div class="equipment-body"><small>${x[1]}</small><h3>${x[2]}</h3><p>${x[3]}</p><div class="price-grid"><div><small>Будні</small><strong>${money(x[4])}</strong></div><div><small>Вихідні</small><strong>${money(x[5])}</strong></div></div></div></article>`).join('')}${kits.map(x=>`<article class="card equipment-card kit-card"><div class="equipment-image kit-composition count-${x[2].length}">${x[2].map(k=>`<div class="kit-product"><img src="${imgs[k]}" alt="${k}"></div>`).join('')}</div><div class="equipment-body"><small>Комплект</small><h3>${x[0]}</h3><p>${x[1]}</p><div class="price-grid"><div><small>Будні</small><strong>${money(x[3])}</strong></div><div><small>Вихідні</small><strong>${money(x[4])}</strong></div><div><small>Сб + Нд</small><strong>${money(x[5])}</strong></div></div></div></article>`).join('')}</div>`}
function renderClients(){const m=new Map();state.bookings.forEach(b=>{const k=b.customer_phone||b.customer_name;if(!k)return;const v=m.get(k)||{name:b.customer_name,phone:b.customer_phone,telegram:b.customer_telegram,count:0,total:0,last:b.start_date};v.count++;v.total+=Number(b.total_amount||0);if(b.start_date>v.last)v.last=b.start_date;m.set(k,v)});const s=$('#globalSearch').value.toLowerCase();const x=[...m.values()].filter(v=>!s||`${v.name} ${v.phone}`.toLowerCase().includes(s));$('#view').innerHTML=`<div class="client-grid">${x.map(v=>`<article class="card client-card"><h3>${v.name}</h3><a href="tel:${v.phone}">${v.phone}</a><p>${v.telegram||'Telegram не вказаний'}</p><div class="client-stats"><span>${v.count} оренд</span><span>${money(v.total)}</span><span>остання ${date(v.last)}</span></div></article>`).join('')||'<div class="card empty">Клієнтів не знайдено.</div>'}</div>`}
function renderAnalytics(){const valid=state.bookings.filter(b=>!['cancelled','declined'].includes(b.status)),rev=valid.reduce((sum,b)=>sum+Number(b.total_amount||0),0),delivery=valid.reduce((sum,b)=>sum+Number(b.delivery_amount||0),0),chemistry=valid.reduce((sum,b)=>sum+calc(b).chemistry,0),extraRevenue=valid.reduce((sum,b)=>sum+extrasTotal(b),0),avg=valid.length?Math.round(rev/valid.length):0,by={},extraBy={};valid.forEach(b=>{const key=b.product_label||products[b.product_code]||b.product_code;const row=by[key]||(by[key]={count:0,revenue:0});row.count+=1;row.revenue+=Number(b.total_amount||0);getSelectedExtras(b).forEach(item=>{const x=extraBy[item.label]||(extraBy[item.label]={count:0,revenue:0});x.count+=1;x.revenue+=Number(item.price||0)})});const arr=Object.entries(by).sort((a,b)=>b[1].count-a[1].count||b[1].revenue-a[1].revenue),extrasArr=Object.entries(extraBy).sort((a,b)=>b[1].revenue-a[1].revenue),max=Math.max(1,...arr.map(x=>x[1].count));$('#view').innerHTML=`<div class="kpi-grid">${[['Бронювань',valid.length],['Виручка',money(rev)],['Середній чек',money(avg)],['Доставка',money(delivery)],['Пакетики Puzzi',money(chemistry)],['Додатково',money(extraRevenue)]].map(x=>`<article class="card kpi"><span>${x[0]}</span><strong>${x[1]}</strong></article>`).join('')}</div><div class="analytics-grid"><article class="card analytics-panel"><h3>Популярність техніки</h3>${arr.map(([n,v])=>`<div class="bar-row"><div class="product-analytics-row"><span>${n}</span><span class="product-stats"><b>${v.count} зам.</b><strong>${money(v.revenue)}</strong></span></div><div class="bar"><i style="width:${v.count/max*100}%"></i></div></div>`).join('')||'<p>Ще немає даних.</p>'}</article><article class="card analytics-panel"><h3>Додаткові позиції</h3>${extrasArr.map(([n,v])=>`<div class="analytics-line"><span>${n}<small>${v.count} зам.</small></span><strong>${money(v.revenue)}</strong></div>`).join('')||'<p>Ще немає продажів.</p>'}</article><article class="card analytics-panel"><h3>Статуси</h3>${Object.entries(statusText).map(([k,l])=>`<div class="analytics-line"><span>${l}</span><strong>${state.bookings.filter(b=>b.status===k).length}</strong></div>`).join('')}</article></div>`}

function renderChemistry(){$('#view').innerHTML=`<div class="chem-grid"><article class="card chem-card"><h2>Хімія до Puzzi</h2><p>Менеджер вводить тільки фактичну кількість використаних пакетиків і ставить відмітку, чи була сторіс.</p><div class="rule"><b>8</b><div><strong>Пакетиків видаємо</strong><span>Невикористані клієнт повертає</span></div><strong>усі використані платні</strong></div><div class="rule"><b>50</b><div><strong>Один пакетик</strong><span>Автоматично додається до фіналу</span></div><strong>грн</strong></div><div class="rule"><b>2</b><div><strong>Безкоштовно за сторіс</strong><span>Віднімаються від використаної кількості</span></div><strong>пакетики</strong></div></article><article class="card chem-card"><h3>Формула</h3><div class="formula">Без сторіс:<br>використано × 50 грн<br><br>Зі сторіс:<br>max(використано − 2, 0) × 50 грн</div><p>Приклад: використано 4, була сторіс → 2 платних × 50 = <b>100 грн</b>.</p></article></div>`}

function minutes(v){const [h,m]=String(v||'00:00').split(':').map(Number);return h*60+m}
function timeOptions(start,end,selected,step=30){let out='';for(let n=minutes(start);n<=minutes(end);n+=step){const v=`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;out+=`<option value="${v}" ${v===selected?'selected':''}>${v}</option>`}return out}
function timeSelect(name,start,end,value){return `<div class="premium-control"><span class="premium-control-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg></span><select name="${name}" required>${timeOptions(start,end,value,30)}</select><span class="premium-chevron">⌄</span></div>`}
function dateControl(name,value){return `<div class="premium-control date-control"><span class="premium-control-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg></span><input name="${name}" type="date" value="${value}" required><button class="picker-trigger" type="button" aria-label="Відкрити календар"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg></button></div>`}
function bindPickerTriggers(root=document){root.querySelectorAll('.date-control').forEach(w=>{const input=w.querySelector('input'),btn=w.querySelector('.picker-trigger');btn.onclick=()=>{if(input.showPicker)input.showPicker();else input.focus()}})}
function renderSettings(){const s=getSlots();$('#view').innerHTML=`<div class="settings-grid"><form class="card settings-card" id="slotsForm"><div class="settings-head"><div><h2>Часові слоти</h2><p>Зміни застосовуються до нових бронювань на цьому пристрої.</p></div></div><div class="slot-editor"><div class="slot-editor-row"><div class="slot-icon">☀</div><div><strong>Ранок</strong><span>Початок і кінець ранкового вікна</span></div><label><small>З</small>${timeSelect("morningStart","00:00","23:30",s.morningStart)}</label><label><small>До</small>${timeSelect("morningEnd","00:00","23:30",s.morningEnd)}</label></div><div class="slot-editor-row"><div class="slot-icon">☾</div><div><strong>Вечір</strong><span>Початок і кінець вечірнього вікна</span></div><label><small>З</small>${timeSelect("eveningStart","00:00","23:30",s.eveningStart)}</label><label><small>До</small>${timeSelect("eveningEnd","00:00","23:30",s.eveningEnd)}</label></div></div><div class="settings-actions"><button class="btn" type="button" id="resetSlots">За замовчуванням</button><button class="btn primary" type="submit">Зберегти слоти</button></div></form><article class="card chem-card"><h2>Фінансова логіка</h2><p>Бронювання дати — 200 грн і входить у загальний розрахунок.</p><p>При статусі «Видано» менеджер обов’язково фіксує залоговий платіж.</p><p>Фінал: бронювання + залог − оренда − доставка − хімія.</p></article></div>`;const form=$('#slotsForm');form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),v={morningStart:String(fd.get('morningStart')),morningEnd:String(fd.get('morningEnd')),eveningStart:String(fd.get('eveningStart')),eveningEnd:String(fd.get('eveningEnd'))};if(v.morningStart>=v.morningEnd||v.eveningStart>=v.eveningEnd||v.morningEnd>=v.eveningStart){toast('Перевірте межі слотів');return}saveSlots(v);toast('Часові слоти збережено')};$('#resetSlots').onclick=()=>{saveSlots(DEFAULT_SLOTS);renderSettings();toast('Повернуто стандартні слоти')}}
function closeDetail(){const y=state.listScroll||0;document.body.classList.remove('detail-open');$('#layer').innerHTML='';state.detail=null;requestAnimationFrame(()=>window.scrollTo({top:y,behavior:'auto'}))}
function openDetail(b){state.listScroll=window.scrollY;state.detail=b;document.body.classList.add('detail-open');const f=calc(b),idx={pending:0,waiting_payment:0,confirmed:1,issued:2,completed:3}[b.status]??0;$('#layer').innerHTML=`<div class="detail"><div class="detail-shell"><div class="detail-top"><button class="back">← До бронювань</button><div class="detail-top-meta"><span>${b.booking_code}</span><small>Створено ${date(b.created_at)}</small></div><div class="detail-quick">${b.status==='confirmed'?'<button class="btn green" data-quick="issue">Видати техніку</button>':''}${b.status==='issued'?'<button class="btn green" data-quick="complete">Закрити оренду</button>':''}<button class="btn" data-quick="edit">Редагувати</button></div></div><section class="detail-hero"><div class="detail-hero-copy"><div class="detail-title-row"><h1>${b.product_label}</h1><span class="hero-status">✓ ${statusText[b.status]}</span></div><div class="period"><b>${date(b.start_date)}</b> · ${tval(b,'pickup_time')} → <b>${date(b.return_date)}</b> · ${tval(b,'return_time')}<small>${b.rental_days||1} доба</small></div></div><div class="hero-images">${pimgs(b).map(i=>`<img src="${i}">`).join('')}</div></section><article class="card flow flow-compact"><div><h3>Хід бронювання</h3><p>Поточний етап: <b>${statusText[b.status]}</b></p></div><div class="steps">${['Нове','Підтверджене','Видано','Повернено'].map((x,i)=>`<div class="step ${i<=idx?'done':''}"><i>${i<=idx?'✓':i+1}</i><b>${x}</b></div>`).join('')}</div></article><div class="detail-grid"><div class="detail-left"><div class="info-grid"><article class="card panel"><h3>Клієнт</h3><h2>${b.customer_name}</h2><p><a href="tel:${b.customer_phone}">${b.customer_phone}</a></p><p>${b.customer_telegram||'Telegram не вказаний'}</p></article><article class="card panel"><h3>Видача</h3><h2>${b.fulfillment==='delivery'?'Доставка':'Самовивіз'}</h2><p>${b.fulfillment==='delivery'?money(b.delivery_amount):'Безкоштовно'}</p><p>${b.fulfillment_address||'вул. Європейська, 146Е'}</p></article>${getSelectedExtras(b).length?`<article class="card panel extras-panel"><h3>Додатково</h3>${getSelectedExtras(b).map(x=>`<div><span>${x.label}</span><strong>${money(x.price)}</strong></div>`).join('')}</article>`:''}<article class="card panel comment"><h3>Коментар</h3><p>${b.customer_comment||b.admin_note||'Коментаря немає'}</p></article></div></div><article class="card panel finance-panel"><h3>Фінанси</h3>${moneyRows(b,f)}</article></div><div class="detail-actions actions">${actions(b)}</div></div></div>`;$('.back').onclick=closeDetail;$$('[data-action]',$('.detail-actions')).forEach(btn=>btn.onclick=()=>handleAction(b,btn.dataset.action));$$('[data-quick]').forEach(btn=>btn.onclick=()=>{const a=btn.dataset.quick;if(a==='issue')openIssue(b);if(a==='complete')openFinance(b,true);if(a==='edit')openBookingForm(b)})}
function moneyRows(b,f){if(f.cancelled)return`<div class="cancel-finance-note">Скасоване бронювання: оренда, доставка та хімія не нараховуються.</div><div class="money-row"><span>Отримано за бронювання</span><strong>${money(f.pre)}</strong></div><div class="money-row"><span>Інші платежі</span><strong>${money(f.issue)}</strong></div><div class="balance refund"><span>Повернути клієнту</span><strong>${money(f.refund)}</strong></div>`;return`<div class="money-row"><span>Оренда</span><strong>${money(b.base_amount)}</strong></div><div class="money-row"><span>Доставка</span><strong>${money(b.delivery_amount)}</strong></div><div class="money-row"><span>Бронювання <small>входить у фінальний розрахунок</small></span><strong>${money(f.pre)}</strong></div><div class="money-row"><span>Залог при видачі <small>вноситься менеджером</small></span><strong>${money(f.issue)}</strong></div>${f.extraItems?`<div class="money-row"><span>Додатково <small>${getSelectedExtras(b).map(x=>x.label).join(', ')}</small></span><strong>${money(f.extraItems)}</strong></div>`:''}${isPuzzi(b)?`<div class="money-row"><span>Хімія <small>${f.used} використано${f.story?' · сторіс ✓':''}</small></span><strong>${money(f.chemistry)}</strong></div>`:''}<div class="money-row"><span>Разом витрати</span><strong>${money(f.expenses)}</strong></div><div class="money-row"><span>Уже отримано</span><strong>${money(f.paid)}</strong></div><div class="balance ${f.refund?'refund':f.due?'due':'neutral'}"><span>${f.refund?'Повернути клієнту':f.due?'Клієнт має доплатити':'Баланс закрито'}</span><strong>${money(f.refund||f.due)}</strong></div>`}
function modal(html){document.body.classList.add('modal-open');$('#layer').innerHTML=`<div class="modal"><button class="modal-backdrop" aria-label="Закрити"></button><div class="modal-card">${html}</div></div>`;$('.modal-backdrop').onclick=closeLayer;$$('[data-close]').forEach(x=>x.onclick=closeLayer)}
function closeLayer(){document.body.classList.remove('modal-open');$('#layer').innerHTML=''}
function live(b,o){const f=calc(b,o);return`<div class="live"><div><span>Бронювання дати</span><strong>${money(f.pre)}</strong></div><div><span>Залог при видачі</span><strong>${money(f.issue)}</strong></div><div><span>Оренда</span><strong>${money(b.base_amount)}</strong></div><div><span>Доставка</span><strong>${money(b.delivery_amount)}</strong></div>${f.extraItems?`<div><span>Додатково</span><strong>${money(f.extraItems)}</strong></div>`:''}${isPuzzi(b)?`<div><span>Хімія</span><strong>${f.used} − ${f.story?2:0} бонус = ${money(f.chemistry)}</strong></div>`:''}<div><span>Разом витрати</span><strong>${money(f.expenses)}</strong></div><div class="balance ${f.refund?'refund':f.due?'due':'neutral'}"><span>${f.refund?'Повернути клієнту':f.due?'Клієнт має доплатити':'Баланс закрито'}</span><strong>${money(f.refund||f.due)}</strong></div></div>`}
function openIssue(b){const f=calc(b),amount=Number(b.deposit_amount||0);modal(`<form class="modal-form issue-form" id="issueForm"><header><div><small>${b.booking_code}</small><h2>Видача техніки</h2></div><button class="close" type="button" data-close>×</button></header><div class="issue-booking-head"><div><small>Техніка</small><strong>${b.product_label}</strong></div><div><small>Клієнт</small><strong>${b.customer_name}</strong></div></div><div class="modal-layout"><section class="modal-section issue-confirm"><h3>Авансовий платіж</h3><div class="issue-amount"><span>Сума, вказана при бронюванні</span><strong>${money(amount)}</strong></div><label class="switch issue-check"><input name="issuePaid" type="checkbox" ${b.deposit_paid?'checked':''}><span><b>Авансовий платіж отримано</b><small>Підтверджую, що клієнт передав ${money(amount)} при видачі.</small></span></label><div class="note">Після підтвердження сума буде врахована у фінальному розрахунку.</div></section><aside class="modal-summary"><h3>Попередній підсумок</h3><div id="live">${live(b,{issue:b.deposit_paid?amount:0,issuePaid:b.deposit_paid})}</div></aside></div><footer><button class="btn" type="button" data-close>Закрити</button><button class="btn primary" type="submit">Підтвердити видачу</button></footer></form>`);const form=$('#issueForm'),box=$('#live'),check=form.issuePaid;const redraw=()=>box.innerHTML=live(b,{issue:check.checked?amount:0,issuePaid:check.checked});check.onchange=redraw;form.onsubmit=async e=>{e.preventDefault();if(!check.checked){toast('Підтвердьте отримання авансового платежу');return}const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await invoke({action:'save_finance',bookingId:b.id,issuePayment:amount,usedPackets:f.used,storyMention:f.story});await invoke({action:'update',bookingId:b.id,status:'issued',adminNote:b.admin_note||''});closeLayer();await load();render();toast('Техніку видано, аванс підтверджено')}catch(err){btn.disabled=false;toast(err.message)}}}
function openFinance(b,complete){const f=calc(b);modal(`<form class="modal-form" id="financeForm"><header><div><small>${b.booking_code}</small><h2>${complete?'Закриття оренди':'Фінальний розрахунок'}</h2></div><button class="close" type="button" data-close>×</button></header><div class="modal-intro"><strong>${b.product_label}</strong><span>${b.customer_name}</span></div><div class="modal-layout"><section class="modal-section"><h3>Дані менеджера</h3><div class="fields"><label class="field"><span>Залог при видачі, грн</span><input name="issue" type="number" min="0" step="50" value="${f.issue}" required></label>${isPuzzi(b)?`<label class="field"><span>Використано пакетиків</span><input name="used" type="number" min="0" max="50" value="${f.used}" required></label><label class="switch"><input name="story" type="checkbox" ${f.story?'checked':''}><span><b>Була відмітка в сторіс</b><small>2 використані пакетики безкоштовно</small></span></label>`:''}</div><div class="note">Менеджер вводить лише фактичні дані. Повернення або доплату система рахує автоматично.</div></section><aside class="modal-summary"><h3>Підсумок</h3><div id="live">${live(b,{issue:f.issue,used:f.used,story:f.story})}</div></aside></div><footer><button class="btn" type="button" data-close>Закрити</button><button class="btn primary" type="submit">${complete?'Зберегти й закрити оренду':'Зберегти розрахунок'}</button></footer></form>`);const form=$('#financeForm'),box=$('#live'),upd=()=>box.innerHTML=live(b,{issue:Number(form.issue.value||0),used:isPuzzi(b)?Number(form.used.value||0):0,story:isPuzzi(b)&&form.story.checked});form.oninput=upd;form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('[type=submit]');btn.disabled=true;try{await invoke({action:'save_finance',bookingId:b.id,issuePayment:Number(form.issue.value||0),usedPackets:isPuzzi(b)?Number(form.used.value||0):0,storyMention:isPuzzi(b)&&form.story.checked});if(complete)await invoke({action:'update',bookingId:b.id,status:'completed',adminNote:b.admin_note||''});closeLayer();await load();render();toast(complete?'Оренду закрито':'Розрахунок збережено')}catch(err){btn.disabled=false;toast(err.message)}}}
