const form=$('#bookingForm');bindPickerTriggers(form);bindTimeWindows(form);const syncExtraCompatibility=()=>{const code=form.productCode.value;form.querySelectorAll('[data-extra-requires]').forEach(label=>{const req=label.dataset.extraRequires?label.dataset.extraRequires.split(',').filter(Boolean):[];const allowed=!req.length||req.includes(code);label.hidden=!allowed;if(!allowed)label.querySelector('input').checked=false})};form.productCode.addEventListener('change',syncExtraCompatibility);syncExtraCompatibility();
const phoneInput=form.customerPhone,lookupBox=form.querySelector('#customerLookup'),nameInput=form.customerName,telegramInput=form.customerTelegram,addressInput=form.deliveryAddress,loyaltyPercentInput=form.loyaltyPercent,loyaltyLevelInput=form.loyaltyLevel,completedOrdersInput=form.completedOrders,manualDiscount=form.discount10;let lookupTimer=0,lastLookupPhone='';
const renderCustomerLookup=(customer)=>{if(!customer){lookupBox.hidden=true;lookupBox.innerHTML='';loyaltyPercentInput.value='0';loyaltyLevelInput.value='Start';completedOrdersInput.value='0';return}const l=customer.loyalty||{level:'Start',percent:0};lookupBox.hidden=false;lookupBox.innerHTML=`<div class="customer-found-head"><div><span>Постійний клієнт</span><strong>${customer.name||customer.phone}</strong></div><b class="loyalty-badge ${String(l.level).toLowerCase()}">${loyaltyLabel(customer)}</b></div><div class="customer-found-stats"><span><b>${customer.completedOrders}</b> завершених оренд</span><span><b>${money(customer.totalSpent)}</b> витрачено</span><span><b>${customer.lastDate?date(customer.lastDate):'—'}</b> остання оренда</span></div>${customer.lastProduct?`<p>Останній вибір: <b>${customer.lastProduct}</b></p>`:''}${customer.address?`<p>Остання адреса: <b>${customer.address}</b></p>`:''}<label class="switch loyalty-switch"><input type="checkbox" name="applyLoyalty" ${l.percent?'checked':''}><span><b>Застосувати лояльність ${l.percent?`−${l.percent}%`:'без знижки'}</b><small>Знижка діє тільки на оренду техніки</small></span></label>`;loyaltyPercentInput.value=String(l.percent||0);loyaltyLevelInput.value=l.level||'Start';completedOrdersInput.value=String(customer.completedOrders||0);const apply=lookupBox.querySelector('[name="applyLoyalty"]');if(apply)apply.onchange=()=>{loyaltyPercentInput.value=apply.checked?String(l.percent||0):'0';if(apply.checked&&Number(l.percent)===10)manualDiscount.checked=false};};
const lookupCustomer=async()=>{const phone=normalizePhone(phoneInput.value);if(!phone||phone===lastLookupPhone)return;if(phone.length<13){renderCustomerLookup(null);return}lastLookupPhone=phone;lookupBox.hidden=false;lookupBox.innerHTML='<div class="customer-loading">Шукаємо клієнта…</div>';try{const {customer}=await invoke({action:'lookup_customer',phone});if(!customer){lookupBox.hidden=false;lookupBox.innerHTML='<div class="customer-new">Новий клієнт · історії оренд ще немає</div>';loyaltyPercentInput.value='0';loyaltyLevelInput.value='Start';completedOrdersInput.value='0';return}if(!b){nameInput.value=customer.name||nameInput.value;telegramInput.value=customer.telegram||telegramInput.value;if(customer.address){addressInput.value=customer.address;form.fulfillment.value='delivery'}}renderCustomerLookup(customer)}catch{lookupBox.hidden=true}};
phoneInput.addEventListener('input',()=>{clearTimeout(lookupTimer);lastLookupPhone='';lookupTimer=setTimeout(lookupCustomer,450)});phoneInput.addEventListener('blur',lookupCustomer);if(phoneInput.value&&!b)setTimeout(lookupCustomer,120);manualDiscount.addEventListener('change',()=>{if(manualDiscount.checked){const apply=lookupBox.querySelector('[name="applyLoyalty"]');if(apply)apply.checked=false;loyaltyPercentInput.value='0'}});
